+func renderWhyDiffLine(line string) string {
+	switch {
+	case strings.HasPrefix(line, "+++") || strings.HasPrefix(line, "---"):
+		return line
+	case strings.HasPrefix(line, "@@"):
+		return line
+	case strings.HasPrefix(line, "+"):
+		return colorizeDiffPrefix("+", "green") + renderWhyHighlightedCode("why.go", line[1:])
+	case strings.HasPrefix(line, "-"):
+		return colorizeDiffPrefix("-", "red") + renderWhyHighlightedCode("why.go", line[1:])
+	case strings.HasPrefix(line, " "):
+		return " " + renderWhyHighlightedCode("why.go", line[1:])
+	default:
+		return line
+	}
+}
+
+func colorizeDiffPrefix(prefix, color string) string {
+	switch color {
+	case "green":
+		return "\x1b[32m" + prefix + "\x1b[0m"
+	case "red":
+		return "\x1b[31m" + prefix + "\x1b[0m"
+	default:
+		return prefix
+	}
+}
