+		}
+
+		start := i
+		for i < len(lines) && strings.HasPrefix(lines[i], "[Tool] ") {
+			i++
+		}
+		count := i - start
+		if count == 1 {
+			out = append(out, lines[start])
+			continue
+		}
+		out = append(out, fmt.Sprintf("[Tools] %d tool calls (press e to expand)", count))
+	}
+
+	return strings.Join(out, "\n")
